const now = new Date();
const weekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);

msg.payload = {
    entity_id: 'event.chunmi_cn_334432105_600f2_water_out_finish_e_7_1',
    start_time: weekAgo.toISOString().slice(0, 19),
    end_time: now.toISOString().slice(0, 19)
};

return msg;

const data = msg.payload;

if (!data || !data.ok) {
    msg.payload = '查询失败: ' + (data?.error || '未知错误');
    return msg;
}

let result = '=====================================\n';
result += '  净水器用水分析报告\n';
result += '=====================================\n';
result += '实体: ' + data.entity_id + '\n';
result += '时间: ' + (data.start_time||'').slice(0,10) + ' ~ ' + (data.end_time||'').slice(0,10) + '\n';
result += '记录: ' + data.total_records + '条 / ' + data.days + '天\n\n';

result += '日期         次数   用水量   TDS入  TDS出  去除率\n';
result += '-----------  ----  -------  -----  -----  ------\n';

let totalWater = 0;
let totalCount = 0;

for (const day of data.daily) {
    totalWater += day.total_l;
    totalCount += day.count;
    result += day.date + '   ';
    result += String(day.count).padStart(4) + '   ';
    result += day.total_l.toFixed(2).padStart(6) + 'L  ';
    result += String(day.avg_tds_in).padStart(5) + '  ';
    result += String(day.avg_tds_out).padStart(5) + '  ';
    result += day.tds_reduction_pct + '%\n';
}

result += '-----------  ----  -------\n';
result += '合计         ' + totalCount + '   ' + totalWater.toFixed(2) + 'L\n';
if (data.days > 0) {
    result += '日均         ' + (totalCount/data.days).toFixed(1) + '   ' + (totalWater/data.days).toFixed(2) + 'L\n';
}

msg.payload = result;
return msg;
